// Code-reading excerpt in an existing project with System.IO.Ports.
void OnDataReceived(object? sender, SerialDataReceivedEventArgs e) {
    var port = (SerialPort)sender!;
    byte[] buffer = new byte[256];
    int n = port.Read(buffer, 0, buffer.Length);
    if (n > 0) {
        byte[] actual = buffer.AsSpan(0, n).ToArray();
        Console.WriteLine($"RX count={n} hex={Convert.ToHexString(actual)}");
        EnqueueToSingleParserOwner(actual);
    }
}
// Do not enqueue all 256 bytes. Do not directly update UI on this thread.
// The owner, queue bounds, closure race and exceptions need a defined policy.
